  | 'colorSecondary'
  | 'colorAction'
  | 'colorDisabled'
  | 'colorError'
  | 'colorPrimary'
  | 'fontSizeInherit';

declare const SvgIcon: React.ComponentType<SvgIconProps>;

export default SvgIcon;

